script:
// ============================================================
// CLIENT SCRIPT: Purchase Receipt
// DocType: Purchase Receipt
// ============================================================
// Paste this entire script in:
// ERPNext > Customization > Client Script > New
// DocType: Purchase Receipt
// ============================================================

frappe.ui.form.on('Purchase Receipt', {

    refresh: function(frm) {
        calculate_invoice_totals_pr(frm);
    },

    onload: function(frm) {
        calculate_invoice_totals_pr(frm);
    }
});

// ─────────────────────────────────────────────
// Child Table: Purchase Receipt Item
// ─────────────────────────────────────────────
frappe.ui.form.on('Purchase Receipt Item', {

    qty:                    function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    rate:                   function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    custom_scheme_qty:      function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    custom_trade_offer:     function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    custom_mrp:             function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    custom_gst_per:         function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    custom_advance_tax_per: function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    custom_fed_per:         function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    discount_percentage:    function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },
    custom_tax_formula:     function(frm, cdt, cdn) { calculate_row_pr(frm, cdt, cdn); },

    items_remove: function(frm) {
        calculate_invoice_totals_pr(frm);
    }
});


// ─────────────────────────────────────────────
// Core Row Calculation — Purchase Receipt
// ─────────────────────────────────────────────
function calculate_row_pr(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    let price        = flt(row.rate);
    let qty          = flt(row.qty);
    let scheme_qty   = flt(row.custom_scheme_qty);
    let trade_offer  = flt(row.custom_trade_offer);
    let mrp          = flt(row.custom_mrp);
    let gst_rate     = flt(row.custom_gst_per);
    let adv_tax_per  = flt(row.custom_advance_tax_per);
    let fed_per      = flt(row.custom_fed_per);
    let discount_per = flt(row.discount_percentage);

    let effective_qty = Math.max(qty - scheme_qty, 0);

    // ── Gross Total ─────────────────────────────
    let gross_total = price * effective_qty;

    // ── Discount / Trade Offer ───────────────────
    let discount_value    = (price * discount_per / 100) * effective_qty;
    let trade_offer_total = trade_offer * effective_qty;

    // ── GST ─────────────────────────────────────
    let gst_amount = 0;
    let formula    = (row.custom_tax_formula || '').toLowerCase();

    if (formula.includes('exempted') || formula.includes('gst exempt')) {
        gst_amount = 0;

    } else if (formula.includes('3rd schedule') || formula.includes('third schedule')) {
        gst_amount = ((mrp / ((100 + gst_rate) / 100)) * (gst_rate / 100)) * effective_qty;

    } else if (formula.includes('discount') && formula.includes('trade offer') && formula.includes('including scheme')) {
        gst_amount = ((price * qty - price * effective_qty * discount_per / 100 - trade_offer * qty) * gst_rate) / 100;

    } else if (formula.includes('discount') && formula.includes('trade offer')) {
        gst_amount = ((price - (price * discount_per / 100) - trade_offer) * (gst_rate / 100)) * effective_qty;

    } else if (formula.includes('discount')) {
        gst_amount = (((price - (price * discount_per / 100)) * (gst_rate / 100)) * effective_qty);

    } else if (formula.includes('trade offer')) {
        gst_amount = ((price - trade_offer) * (gst_rate / 100)) * effective_qty;

    } else if (formula.includes('with scheme') || formula.includes('including scheme')) {
        gst_amount = price * qty * (gst_rate / 100);

    } else {
        gst_amount = price * effective_qty * (gst_rate / 100);
    }

    // ── FED ──────────────────────────────────────
    let fed_amount = price * effective_qty * (fed_per / 100);

    // ── Advance Tax ──────────────────────────────
    let adv_tax_amount = 0;

    if (adv_tax_per > 0) {
        if (formula.includes('adv exempt') || formula.includes('advance tax exempt')) {
            adv_tax_amount = 0;

        } else if (formula.includes('fed') && formula.includes('discount') && formula.includes('trade offer')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount + fed_amount - trade_offer_total) / 100;

        } else if (formula.includes('discount') && formula.includes('trade offer')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount - trade_offer_total) / 100;

        } else if (formula.includes('trade offer')) {
            adv_tax_amount = adv_tax_per * (gross_total - trade_offer_total + gst_amount) / 100;

        } else if (formula.includes('gst') && formula.includes('discount')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount) / 100;

        } else if (formula.includes('discount')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value) / 100;

        } else {
            adv_tax_amount = adv_tax_per * gross_total / 100;
        }
    }

    // ── Line Total ───────────────────────────────
    let line_total = gross_total - discount_value + gst_amount + adv_tax_amount - trade_offer_total + fed_amount;

    // ── Base Cost Price (per unit landed cost) ───
    // This is critical for inventory valuation in ERPNext
    let fed_per_unit    = (qty > 0) ? (fed_amount / qty) : 0;
    let base_cost_price = price - (price * discount_per / 100) - trade_offer + fed_per_unit;

    // ── Write back ───────────────────────────────
    frappe.model.set_value(cdt, cdn, 'custom_gst_amount',          flt(gst_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_advance_tax_amount',  flt(adv_tax_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_fed_amount',          flt(fed_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_gross_total',         flt(gross_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_line_total',          flt(line_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_base_cost_price',     flt(base_cost_price, 4));

    // ── CRITICAL: Sync valuation_rate for inventory ──
    // ERPNext uses valuation_rate to post stock value
    frappe.model.set_value(cdt, cdn, 'valuation_rate', flt(base_cost_price, 4));

    // Sync ERPNext amount
    frappe.model.set_value(cdt, cdn, 'amount', flt(line_total, 2));

    calculate_invoice_totals_pr(frm);
}


// ─────────────────────────────────────────────
// Header Totals — Purchase Receipt
// ─────────────────────────────────────────────
function calculate_invoice_totals_pr(frm) {
    let total_qty         = 0;
    let total_gross       = 0;
    let total_gst         = 0;
    let total_adv_tax     = 0;
    let total_fed         = 0;
    let total_line        = 0;

    (frm.doc.items || []).forEach(function(row) {
        total_qty     += flt(row.qty);
        total_gross   += flt(row.custom_gross_total);
        total_gst     += flt(row.custom_gst_amount);
        total_adv_tax += flt(row.custom_advance_tax_amount);
        total_fed     += flt(row.custom_fed_amount);
        total_line    += flt(row.custom_line_total);
    });

    if (frm.fields_dict['custom_total_gross'])
        frm.set_value('custom_total_gross',       flt(total_gross, 2));
    if (frm.fields_dict['custom_total_gst'])
        frm.set_value('custom_total_gst',         flt(total_gst, 2));
    if (frm.fields_dict['custom_total_advance_tax'])
        frm.set_value('custom_total_advance_tax', flt(total_adv_tax, 2));
    if (frm.fields_dict['custom_total_fed'])
        frm.set_value('custom_total_fed',         flt(total_fed, 2));
    if (frm.fields_dict['custom_grand_line_total'])
        frm.set_value('custom_grand_line_total',  flt(total_line, 2));

    frm.set_value('total_qty', total_qty);

    frm.refresh_fields();
}

// ============================================================
// CLIENT SCRIPT: Purchase Invoice
// DocType: Purchase Invoice
// ============================================================
// Paste this entire script in:
// ERPNext > Customization > Client Script > New
// DocType: Purchase Invoice
// ============================================================

frappe.ui.form.on('Purchase Invoice', {

    refresh: function(frm) {
        calculate_invoice_totals_pi(frm);
    },

    onload: function(frm) {
        calculate_invoice_totals_pi(frm);
    }
});

// ─────────────────────────────────────────────
// Child Table: Purchase Invoice Item
// ─────────────────────────────────────────────
frappe.ui.form.on('Purchase Invoice Item', {

    qty:                    function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    rate:                   function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    custom_scheme_qty:      function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    custom_trade_offer:     function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    custom_mrp:             function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    custom_gst_per:         function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    custom_advance_tax_per: function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    custom_fed_per:         function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    discount_percentage:    function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },
    custom_tax_formula:     function(frm, cdt, cdn) { calculate_row_pi(frm, cdt, cdn); },

    items_remove: function(frm) {
        calculate_invoice_totals_pi(frm);
    }
});


// ─────────────────────────────────────────────
// Core Row Calculation — Purchase Invoice
// ─────────────────────────────────────────────
function calculate_row_pi(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    let price        = flt(row.rate);
    let qty          = flt(row.qty);
    let scheme_qty   = flt(row.custom_scheme_qty);
    let trade_offer  = flt(row.custom_trade_offer);
    let mrp          = flt(row.custom_mrp);
    let gst_rate     = flt(row.custom_gst_per);
    let adv_tax_per  = flt(row.custom_advance_tax_per);
    let fed_per      = flt(row.custom_fed_per);
    let discount_per = flt(row.discount_percentage);

    let effective_qty = Math.max(qty - scheme_qty, 0);

    // ── Gross Total ─────────────────────────────
    let gross_total = price * effective_qty;

    // ── Discount Value ──────────────────────────
    let discount_value = (price * discount_per / 100) * effective_qty;

    // ── Trade Offer Total ───────────────────────
    let trade_offer_total = trade_offer * effective_qty;

    // ── GST ─────────────────────────────────────
    let gst_amount = 0;
    let formula    = (row.custom_tax_formula || '').toLowerCase();

    if (formula.includes('exempted') || formula.includes('gst exempt')) {
        gst_amount = 0;

    } else if (formula.includes('3rd schedule') || formula.includes('third schedule')) {
        gst_amount = ((mrp / ((100 + gst_rate) / 100)) * (gst_rate / 100)) * effective_qty;

    } else if (formula.includes('discount') && formula.includes('trade offer') && formula.includes('including scheme')) {
        // Including Scheme variant
        gst_amount = ((price * qty - price * effective_qty * discount_per / 100 - trade_offer * qty) * gst_rate) / 100;

    } else if (formula.includes('discount') && formula.includes('trade offer')) {
        gst_amount = ((price - (price * discount_per / 100) - trade_offer) * (gst_rate / 100)) * effective_qty;

    } else if (formula.includes('discount')) {
        gst_amount = (((price - (price * discount_per / 100)) * (gst_rate / 100)) * effective_qty);

    } else if (formula.includes('trade offer')) {
        gst_amount = ((price - trade_offer) * (gst_rate / 100)) * effective_qty;

    } else if (formula.includes('with scheme') || formula.includes('including scheme')) {
        gst_amount = price * qty * (gst_rate / 100);

    } else {
        gst_amount = price * effective_qty * (gst_rate / 100);
    }

    // ── FED ──────────────────────────────────────
    let fed_amount = price * effective_qty * (fed_per / 100);

    // ── Advance Tax ──────────────────────────────
    let adv_tax_amount = 0;

    if (adv_tax_per > 0) {
        if (formula.includes('adv exempt') || formula.includes('advance tax exempt')) {
            adv_tax_amount = 0;

        } else if (formula.includes('fed') && formula.includes('discount') && formula.includes('trade offer')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount + fed_amount - trade_offer_total) / 100;

        } else if (formula.includes('discount') && formula.includes('trade offer')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount - trade_offer_total) / 100;

        } else if (formula.includes('trade offer')) {
            adv_tax_amount = adv_tax_per * (gross_total - trade_offer_total + gst_amount) / 100;

        } else if (formula.includes('gst') && formula.includes('discount')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount) / 100;

        } else if (formula.includes('discount')) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value) / 100;

        } else {
            adv_tax_amount = adv_tax_per * gross_total / 100;
        }
    }

    // ── Line Total ───────────────────────────────
    let line_total = gross_total - discount_value + gst_amount + adv_tax_amount - trade_offer_total + fed_amount;

    // ── Base Cost Price (per unit) ───────────────
    let fed_per_unit    = (qty > 0) ? (fed_amount / qty) : 0;
    let base_cost_price = price - (price * discount_per / 100) - trade_offer + fed_per_unit;

    // ── Write back ───────────────────────────────
    frappe.model.set_value(cdt, cdn, 'custom_gst_amount',          flt(gst_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_advance_tax_amount',  flt(adv_tax_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_fed_amount',          flt(fed_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_gross_total',         flt(gross_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_line_total',          flt(line_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_base_cost_price',     flt(base_cost_price, 4));

    // Sync ERPNext amount field
    frappe.model.set_value(cdt, cdn, 'amount', flt(line_total, 2));

    calculate_invoice_totals_pi(frm);
}


// ─────────────────────────────────────────────
// Header Totals — Purchase Invoice
// ─────────────────────────────────────────────
function calculate_invoice_totals_pi(frm) {
    let total_qty         = 0;
    let total_gross       = 0;
    let total_gst         = 0;
    let total_adv_tax     = 0;
    let total_fed         = 0;
    let total_line        = 0;

    (frm.doc.items || []).forEach(function(row) {
        total_qty     += flt(row.qty);
        total_gross   += flt(row.custom_gross_total);
        total_gst     += flt(row.custom_gst_amount);
        total_adv_tax += flt(row.custom_advance_tax_amount);
        total_fed     += flt(row.custom_fed_amount);
        total_line    += flt(row.custom_line_total);
    });

    if (frm.fields_dict['custom_total_gross'])
        frm.set_value('custom_total_gross',       flt(total_gross, 2));
    if (frm.fields_dict['custom_total_gst'])
        frm.set_value('custom_total_gst',         flt(total_gst, 2));
    if (frm.fields_dict['custom_total_advance_tax'])
        frm.set_value('custom_total_advance_tax', flt(total_adv_tax, 2));
    if (frm.fields_dict['custom_total_fed'])
        frm.set_value('custom_total_fed',         flt(total_fed, 2));
    if (frm.fields_dict['custom_grand_line_total'])
        frm.set_value('custom_grand_line_total',  flt(total_line, 2));

    frm.set_value('total_qty', total_qty);

    // Sync ERPNext grand_total with our line total sum
    // (taxes are embedded in line_total already)
    frm.set_value('total', flt(total_line, 2));

    frm.refresh_fields();
}

// ============================================================
// CLIENT SCRIPT — Purchase Invoice
// DocType: Purchase Invoice
// ============================================================
// RULES:
//   - NEVER modify row.qty from client script
//   - qty = what user types (paid units) — never changed
//   - scheme_qty = free units (user types separately)
//   - inventory_qty = qty + scheme_qty (stored in custom_inventory_qty)
//   - Client script ONLY calculates tax amounts and totals for display
// ============================================================

frappe.ui.form.on('Purchase Invoice', {

    onload: function(frm) {
        if (!frm.doc.custom_gst_input_account) {
            autofill_accounts_from_buying_settings(frm);
        }
        calculate_invoice_totals(frm);
    },

    refresh: function(frm) {
        calculate_invoice_totals(frm);
    }
});

// ─────────────────────────────────────────────────────────────
// Auto-fill account fields from Buying Settings
// ─────────────────────────────────────────────────────────────
function autofill_accounts_from_buying_settings(frm) {
    frappe.db.get_single_value('Buying Settings', 'custom_gst_input_account').then(function(val) {
        if (val) frm.set_value('custom_gst_input_account', val);
    });
    frappe.db.get_single_value('Buying Settings', 'custom_advance_tax_account').then(function(val) {
        if (val) frm.set_value('custom_advance_tax_account', val);
    });
    frappe.db.get_single_value('Buying Settings', 'custom_fed_account').then(function(val) {
        if (val) frm.set_value('custom_fed_account', val);
    });
    frappe.db.get_single_value('Buying Settings', 'custom_trade_offer_account').then(function(val) {
        if (val) frm.set_value('custom_trade_offer_account', val);
    });
}

// ─────────────────────────────────────────────────────────────
// Child table triggers — only fields that affect calculations
// ─────────────────────────────────────────────────────────────
frappe.ui.form.on('Purchase Invoice Item', {
    qty:                    function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    rate:                   function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    custom_scheme_qty:      function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    custom_trade_offer:     function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    custom_mrp:             function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    custom_gst_per:         function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    custom_advance_tax_per: function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    custom_fed_per:         function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    discount_percentage:    function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    custom_tax_formula:     function(frm, cdt, cdn) { calculate_row(frm, cdt, cdn); },
    items_remove:           function(frm)           { calculate_invoice_totals(frm); }
});

// ─────────────────────────────────────────────────────────────
// Row calculation — display only, NEVER modifies qty
// ─────────────────────────────────────────────────────────────
function calculate_row(frm, cdt, cdn) {
    var row = locals[cdt][cdn];

    var price        = flt(row.rate);
    var qty          = flt(row.qty);               // paid units — never changed
    var scheme_qty   = flt(row.custom_scheme_qty); // free units — never changed
    var trade_offer  = flt(row.custom_trade_offer);
    var mrp          = flt(row.custom_mrp);
    var gst_rate     = flt(row.custom_gst_per);
    var adv_tax_per  = flt(row.custom_advance_tax_per);
    var fed_per      = flt(row.custom_fed_per);
    var discount_per = flt(row.discount_percentage);
    var formula      = (row.custom_tax_formula || '').toLowerCase();

    // Tax calculated on paid units only
    var effective_qty = qty - scheme_qty;
    if (effective_qty < 0) effective_qty = 0;

    // FIX: inventory_qty stored in custom_inventory_qty — row.qty never touched
    var inventory_qty = qty + scheme_qty;

    // ── Gross total ──────────────────────────────────────────
    var gross_total       = price * effective_qty;
    var discount_value    = (price * discount_per / 100) * effective_qty;
    var trade_offer_total = trade_offer * effective_qty;
    var fed_amount        = price * effective_qty * (fed_per / 100);

    // ── GST ──────────────────────────────────────────────────
    var gst_amount = 0;
    if (formula.indexOf('exempted') >= 0 || formula.indexOf('gst exempt') >= 0) {
        gst_amount = 0;
    } else if (formula.indexOf('3rd schedule') >= 0 || formula.indexOf('third schedule') >= 0) {
        gst_amount = ((mrp / ((100 + gst_rate) / 100)) * (gst_rate / 100)) * effective_qty;
    } else if (formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0 && formula.indexOf('including scheme') >= 0) {
        gst_amount = ((price * qty - price * effective_qty * discount_per / 100 - trade_offer * qty) * gst_rate) / 100;
    } else if (formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0) {
        gst_amount = ((price - (price * discount_per / 100) - trade_offer) * (gst_rate / 100)) * effective_qty;
    } else if (formula.indexOf('discount') >= 0) {
        gst_amount = ((price - (price * discount_per / 100)) * (gst_rate / 100)) * effective_qty;
    } else if (formula.indexOf('trade offer') >= 0) {
        gst_amount = ((price - trade_offer) * (gst_rate / 100)) * effective_qty;
    } else if (formula.indexOf('with scheme') >= 0 || formula.indexOf('including scheme') >= 0) {
        gst_amount = price * qty * (gst_rate / 100);
    } else {
        gst_amount = price * effective_qty * (gst_rate / 100);
    }

    // ── Advance Tax ──────────────────────────────────────────
    var adv_tax_amount = 0;
    if (adv_tax_per > 0) {
        if (formula.indexOf('adv exempt') >= 0 || formula.indexOf('advance tax exempt') >= 0) {
            adv_tax_amount = 0;
        } else if (formula.indexOf('fed') >= 0 && formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount + fed_amount - trade_offer_total) / 100;
        } else if (formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount - trade_offer_total) / 100;
        } else if (formula.indexOf('trade offer') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - trade_offer_total + gst_amount) / 100;
        } else if (formula.indexOf('gst') >= 0 && formula.indexOf('discount') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount) / 100;
        } else if (formula.indexOf('discount') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value) / 100;
        } else {
            adv_tax_amount = adv_tax_per * gross_total / 100;
        }
    }

    // ── Line total ───────────────────────────────────────────
    var line_total = gross_total - discount_value + gst_amount + adv_tax_amount - trade_offer_total + fed_amount;

    // ── Valuation rate for display only ──────────────────────
    var valuation_rate = (inventory_qty > 0) ? (line_total / inventory_qty) : 0;

    // ── Write ONLY calculated fields — qty is NEVER touched ──
    frappe.model.set_value(cdt, cdn, 'custom_gst_amount',         flt(gst_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_advance_tax_amount', flt(adv_tax_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_fed_amount',         flt(fed_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_gross_total',        flt(gross_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_line_total',         flt(line_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_base_cost_price',    flt(valuation_rate, 4));
    frappe.model.set_value(cdt, cdn, 'custom_inventory_qty',      flt(inventory_qty, 3));  // FIX: store here not in qty
    frappe.model.set_value(cdt, cdn, 'amount',                    flt(line_total, 2));
    // row.qty is NEVER set here

    calculate_invoice_totals(frm);
}

// ─────────────────────────────────────────────────────────────
// Header totals
// ─────────────────────────────────────────────────────────────
function calculate_invoice_totals(frm) {
    var total_qty     = 0;
    var total_gross   = 0;
    var total_gst     = 0;
    var total_adv_tax = 0;
    var total_fed     = 0;
    var total_line    = 0;

    (frm.doc.items || []).forEach(function(row) {
        var qty        = flt(row.qty);
        var scheme_qty = flt(row.custom_scheme_qty);
        total_qty     += qty + scheme_qty;  
        total_gross   += flt(row.custom_gross_total);
        total_gst     += flt(row.custom_gst_amount);
        total_adv_tax += flt(row.custom_advance_tax_amount);
        total_fed     += flt(row.custom_fed_amount);
        total_line    += flt(row.custom_line_total);
    });

    if (frm.fields_dict['custom_total_gross'])
        frm.set_value('custom_total_gross',       flt(total_gross, 2));
    if (frm.fields_dict['custom_total_gst'])
        frm.set_value('custom_total_gst',         flt(total_gst, 2));
    if (frm.fields_dict['custom_total_advance_tax'])
        frm.set_value('custom_total_advance_tax', flt(total_adv_tax, 2));
    if (frm.fields_dict['custom_total_fed'])
        frm.set_value('custom_total_fed',         flt(total_fed, 2));
    if (frm.fields_dict['custom_grand_line_total'])
        frm.set_value('custom_grand_line_total',  flt(total_line, 2));

    frm.set_value('total_qty', total_qty);
    frm.set_value('total',     flt(total_line, 2));
    frm.refresh_fields();
}

