            return number;
        }

        function parseFactor() {
            if (peek() === "(") {
                consume();

                const value = parseExpression();

                if (consume() !== ")") {
                    throw new Error("Missing closing parenthesis");
                }

                return value;
            }

            return parseNumber();
        }

        function parseTerm() {
            let value = parseFactor();

            while (peek() === "*" || peek() === "/") {
                const operator = consume();
                const right = parseFactor();

                if (operator === "*") {
                    value *= right;
                } else {
                    if (right === 0) {
                        throw new Error("Division by zero");
                    }

                    value /= right;
                }
            }

            return value;
        }

        function parseExpression() {
            let value = parseTerm();

            while (peek() === "+" || peek() === "-") {
                const operator = consume();
                const right = parseTerm();

                if (operator === "+") {
                    value += right;
                } else {
                    value -= right;
                }
            }

            return value;
        }

        const result = parseExpression();

        if (position !== input.length) {
            throw new Error(
                `Unexpected character at position ${position}`
            );
        }

        return result;
    }

    function replaceVariables(expression, namespace) {
        let result = String(expression || "");

        Object.keys(namespace)
            .sort((a, b) => b.length - a.length)
            .forEach(key => {
                const escaped = key.replace(
                    /[.*+?^${}()|[\]\\]/g,
                    "\\$&"
                );

                result = result.replace(
                    new RegExp(`\\b${escaped}\\b`, "g"),
                    String(flt(namespace[key]))
                );
            });

        const invalid = result.match(/[A-Za-z_]/);

        if (invalid) {
            throw new Error(
                `Unknown formula variable near "${invalid[0]}"`
            );
        }

        return result;
    }

    async function getFormula(formulaName) {
        if (!formulaName) {
            return null;
        }

        if (formulaCache[formulaName]) {
            return formulaCache[formulaName];
        }

        const response = await frappe.db.get_value(
            "Tax Formula",
            formulaName,
            [
                "formula_string",
                "gst_account",
                "advance_tax_account"
            ]
        );

        const formula = response.message || {};

        formulaCache[formulaName] = formula;

        return formula;
    }

    async function calculateFormula(
        formulaName,
        namespace
    ) {
        if (!formulaName) {
            return 0;
        }

        const formulaRecord = await getFormula(formulaName);
        const formulaString =
            formulaRecord?.formula_string || "";

        if (!formulaString) {
            return 0;
        }

        const numericExpression = replaceVariables(
            formulaString,
            namespace
        );

        return flt4(
            evaluateArithmetic(numericExpression)
        );
    }

    function rowCameFromReceipt(row) {
        return Boolean(
            row.purchase_receipt ||
            row.purchase_receipt_item
        );
    }

    function setCommercialFieldsReadonly(frm) {
        const hasReceiptItems = (frm.doc.items || [])
            .some(rowCameFromReceipt);

        const lockedFields = [
            "custom_vendor_rate",
            "custom_scheme_qty",
            "custom_discount_per",
            "custom_trade_offer",
            "custom_mrp",
            "custom_fed_per",
            "custom_fed_formula"
        ];

        lockedFields.forEach(fieldname => {
            frm.fields_dict.items.grid
                .update_docfield_property(
                    fieldname,
                    "read_only",
                    hasReceiptItems ? 1 : 0
                );
        });

        frm.refresh_field("items");
    }

    async function calculateRow(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        const vendorRate = flt(
            row.custom_vendor_rate ||
            row.price_list_rate ||
            row.rate
        );

        const qty = flt(row.qty);
        const schemeQty = flt(row.custom_scheme_qty);
        const discountPer = flt(
            row.custom_discount_per
        );
        const tradeOfferTotal = flt(row.custom_trade_offer_total);
        const mrp = flt(row.custom_mrp);

        const gstPer = flt(row.custom_gst_per);
        const advanceTaxPer = flt(
            row.custom_advance_tax_per
        );
        const fedPer = flt(row.custom_fed_per);

        if (schemeQty > qty) {
            frappe.show_alert({
                message:
                    `Scheme quantity exceeds quantity for ${
                        row.item_code || "item"
                    }`,
                indicator: "red"
            });

            return;
        }

        const paidQty = qty - schemeQty;
        const grossTotal = vendorRate * qty;

        const discountAmount =
            vendorRate *
            discountPer /
            100 *
            paidQty;

        const tradeOffer =
            paidQty ? tradeOfferTotal / paidQty : 0;

        const namespace = {
            rate: vendorRate,
            qty,
            custom_scheme_qty: schemeQty,
            custom_discount_per: discountPer,
            custom_trade_offer: tradeOffer,
            custom_mrp: mrp,
            custom_gst_per: gstPer,
            custom_advance_tax_per: advanceTaxPer,
            custom_fed_per: fedPer,
            custom_gross_total: grossTotal,
            custom_discount_amnt: discountAmount,
            custom_trade_offer_total: tradeOfferTotal,
            custom_gst_amount: 0,
            custom_advance_tax_amount: 0,
            custom_fed_amount: 0
        };

        let fedAmount = 0;

        if (row.custom_fed_formula) {
            fedAmount = await calculateFormula(
                row.custom_fed_formula,
                namespace
            );
        } else if (fedPer) {
            fedAmount =
                vendorRate *
                paidQty *
                fedPer /
                100;
        }

        namespace.custom_fed_amount = fedAmount;

        const gstAmount = await calculateFormula(
            row.custom_gst_formula,
            namespace
        );

        namespace.custom_gst_amount = gstAmount;

        const advanceTaxAmount = await calculateFormula(
            row.custom_advance_tax_formula,
            namespace
        );

        const rowNetAmount =
            grossTotal -
            discountAmount -
            tradeOfferTotal +
            fedAmount;

        const netUnitCost = qty
            ? rowNetAmount / qty
            : 0;

        const lineTotal =
            rowNetAmount +
            gstAmount +
            advanceTaxAmount;

        const values = {
            custom_vendor_rate: flt4(vendorRate),
            custom_gross_total: flt4(grossTotal),
            custom_discount_amnt: flt4(discountAmount),
            custom_trade_offer_total:
                flt4(tradeOfferTotal),
            custom_trade_offer:
                flt4(tradeOffer),
            custom_fed_amount: flt4(fedAmount),
            custom_gst_amount: flt4(gstAmount),
            custom_advance_tax_amount:
                flt4(advanceTaxAmount),
            custom_price_without_taxes:
                flt4(netUnitCost),
            custom_price_after_taxes:
                flt4(qty ? lineTotal / qty : 0),
            custom_line_total: flt4(lineTotal),

            // Server will enforce this again.
            price_list_rate: flt4(vendorRate),
            rate: flt4(netUnitCost),

            // Stop ERPNext standard discount from applying again.
            discount_percentage: 0,
            discount_amount: 0
        };

        for (const [fieldname, value] of Object.entries(values)) {
            if (flt(row[fieldname]) !== flt(value)) {
                await frappe.model.set_value(
                    cdt,
                    cdn,
                    fieldname,
                    value
                );
            }
        }
    }

    async function calculateDocument(frm) {
        if (calculationRunning || frm.doc.docstatus !== 0) {
            return;
        }

        calculationRunning = true;

        try {
            await frm.set_value("ignore_pricing_rule", 1);

            for (const row of frm.doc.items || []) {
                await calculateRow(
                    frm,
                    row.doctype,
                    row.name
                );
            }

            const totals = (frm.doc.items || []).reduce(
                (acc, row) => {
                    acc.gross += flt(
                        row.custom_gross_total
                    );

                    acc.discount += flt(
                        row.custom_discount_amnt
                    );

                    acc.trade += flt(
                        row.custom_trade_offer_total
                    );

                    acc.fed += flt(
                        row.custom_fed_amount
                    );

                    acc.gst += flt(
                        row.custom_gst_amount
                    );

                    acc.advance += flt(
                        row.custom_advance_tax_amount
                    );

                    acc.grand += flt(
                        row.custom_line_total
                    );

                    return acc;
                },
                {
                    gross: 0,
                    discount: 0,
                    trade: 0,
                    fed: 0,
                    gst: 0,
                    advance: 0,
                    grand: 0
                }
            );

            await frm.set_value({
                custom_total_gross: flt4(totals.gross),
                custom_total_discount:
                    flt4(totals.discount),
                custom_total_trade_offer:
                    flt4(totals.trade),
                custom_total_fed: flt4(totals.fed),
                custom_total_gst: flt4(totals.gst),
                custom_total_advance_tax:
                    flt4(totals.advance),
                custom_grand_line_total:
                    flt4(totals.grand)
            });

            frm.refresh_fields();
        } catch (error) {
            console.error(
                "Custom purchase calculation failed:",
                error
            );

            frappe.msgprint({
                title: __("Calculation Error"),
                indicator: "red",
                message: frappe.utils.escape_html(
                    error.message || String(error)
                )
            });
        } finally {
            calculationRunning = false;
        }
    }

    function scheduleCalculation(frm) {
        clearTimeout(calculationTimer);

        calculationTimer = setTimeout(() => {
            calculateDocument(frm);
        }, 250);
    }

    function showCalculationPreview(frm) {
        const rows = (frm.doc.items || [])
            .map(row => `
                <tr>
                    <td>${frappe.utils.escape_html(
                        row.item_code || ""
                    )}</td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_vendor_rate,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">${flt(row.qty)}</td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_gross_total,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_discount_amnt,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_trade_offer_total,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_fed_amount,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_gst_amount,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_advance_tax_amount,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_line_total,
                            frm.doc.currency
                        )}
                    </td>
                </tr>
            `)
            .join("");

        frappe.msgprint({
            title: __("Live Purchase Calculation"),
            indicator: "blue",
            wide: true,
            message: `
                <div style="overflow-x:auto">
                    <table class="table table-bordered">
                        <thead>
                            <tr>
                                <th>Item</th>
                                <th>Vendor Rate</th>
                                <th>Qty</th>
                                <th>Gross</th>
                                <th>Discount</th>
                                <th>Trade Offer</th>
                                <th>FED</th>
                                <th>GST</th>
                                <th>Advance Tax</th>
                                <th>Line Total</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>

                    <hr>

                    <b>Gross:</b>
                    ${format_currency(
                        frm.doc.custom_total_gross,
                        frm.doc.currency
                    )}<br>

                    <b>Discount:</b>
                    ${format_currency(
                        frm.doc.custom_total_discount,
                        frm.doc.currency
                    )}<br>

                    <b>Trade Offer:</b>
                    ${format_currency(
                        frm.doc.custom_total_trade_offer,
                        frm.doc.currency
                    )}<br>

                    <b>FED:</b>
                    ${format_currency(
                        frm.doc.custom_total_fed,
                        frm.doc.currency
                    )}<br>

                    <b>GST:</b>
                    ${format_currency(
                        frm.doc.custom_total_gst,
                        frm.doc.currency
                    )}<br>

                    <b>Advance Tax:</b>
                    ${format_currency(
                        frm.doc.custom_total_advance_tax,
                        frm.doc.currency
                    )}<br>

                    <b>Expected Invoice Total:</b>
                    ${format_currency(
                        frm.doc.custom_grand_line_total,
                        frm.doc.currency
                    )}
                </div>
            `
        });
    }

    frappe.ui.form.on("Purchase Invoice", {
        setup(frm) {
            frm.set_query(
                "custom_gst_formula",
                "items",
                () => ({
                    filters: {
                        formula_type: "gst"
                    }
                })
            );

            frm.set_query(
                "custom_advance_tax_formula",
                "items",
                () => ({
                    filters: {
                        formula_type: "advance_tax"
                    }
                })
            );

            frm.set_query(
                "custom_fed_formula",
                "items",
                () => ({
                    filters: {
                        formula_type: "fed"
                    }
                })
            );
        },

        onload(frm) {
            frm.set_value("ignore_pricing_rule", 1);
            setCommercialFieldsReadonly(frm);
        },

        refresh(frm) {
            setCommercialFieldsReadonly(frm);

            if (frm.doc.docstatus === 0) {
                frm.add_custom_button(
                    __("Recalculate Custom Costs"),
                    async () => {
                        await calculateDocument(frm);

                        frappe.show_alert({
                            message:
                                __("Custom values recalculated"),
                            indicator: "green"
                        });
                    },
                    __("Custom Calculation")
                );

                frm.add_custom_button(
                    __("Show Live Calculation"),
                    async () => {
                        await calculateDocument(frm);
                        showCalculationPreview(frm);
                    },
                    __("Custom Calculation")
                );
            }
        },

        validate(frm) {
            return calculateDocument(frm);
        },

        items_add(frm) {
            scheduleCalculation(frm);
        },

        items_remove(frm) {
            scheduleCalculation(frm);
        }
    });

    const rowTriggers = [
        "qty",
        "custom_vendor_rate",
        "custom_scheme_qty",
        "custom_discount_per",
        "custom_trade_offer",
        "custom_mrp",
        "custom_gst_per",
        "custom_gst_formula",
        "custom_advance_tax_per",
        "custom_advance_tax_formula",
        "custom_fed_per",
        "custom_fed_formula",
        "custom_is_3rd_schedule"
    ];

    const childEvents = {};

    rowTriggers.forEach(fieldname => {
        childEvents[fieldname] = function (
            frm,
            cdt,
            cdn
        ) {
            scheduleCalculation(frm);
        };
    });

    childEvents.purchase_receipt = function (frm) {
        setCommercialFieldsReadonly(frm);
        scheduleCalculation(frm);
    };

    childEvents.purchase_receipt_item = function (frm) {
        setCommercialFieldsReadonly(frm);
        scheduleCalculation(frm);
    };

    frappe.ui.form.on(
        "Purchase Invoice Item",
        childEvents
    );
})();

