    function rowCameFromReceipt(row) {
        return Boolean(
            row.purchase_receipt ||
            row.purchase_receipt_item
        );
    }

    function setCommercialFieldsReadonly(frm) {
        const hasReceiptItems = (frm.doc.items || [])
            .some(rowCameFromReceipt);

        const lockedFields = [
            "custom_vendor_rate",
            "custom_scheme_qty",
            "custom_discount_per",
            "custom_trade_offer",
            "custom_mrp",
            "custom_fed_per",
            "custom_fed_formula"
        ];

        lockedFields.forEach(fieldname => {
            frm.fields_dict.items.grid
                .update_docfield_property(
                    fieldname,
                    "read_only",
                    hasReceiptItems ? 1 : 0
                );
        });

        frm.refresh_field("items");
    }

    async function calculateRow(frm, cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        const vendorRate = flt(
            row.custom_vendor_rate ||
            row.price_list_rate ||
            row.rate
        );

        const qty = flt(row.qty);
        const schemeQty = flt(row.custom_scheme_qty);
        const discountPer = flt(
            row.custom_discount_per
        );
        const tradeOffer = flt(row.custom_trade_offer);
        const mrp = flt(row.custom_mrp);

        const gstPer = flt(row.custom_gst_per);
        const advanceTaxPer = flt(
            row.custom_advance_tax_per
        );
        const fedPer = flt(row.custom_fed_per);

        if (schemeQty > qty) {
            frappe.show_alert({
                message:
                    `Scheme quantity exceeds quantity for ${
                        row.item_code || "item"
                    }`,
                indicator: "red"
            });

            return;
        }

        const paidQty = qty - schemeQty;
        const grossTotal = vendorRate * qty;

        const discountAmount =
            vendorRate *
            discountPer /
            100 *
            paidQty;

        const tradeOfferTotal =
            tradeOffer * paidQty;

        const namespace = {
            rate: vendorRate,
            qty,
            custom_scheme_qty: schemeQty,
            custom_discount_per: discountPer,
            custom_trade_offer: tradeOffer,
            custom_mrp: mrp,
            custom_gst_per: gstPer,
            custom_advance_tax_per: advanceTaxPer,
            custom_fed_per: fedPer,
            custom_gross_total: grossTotal,
            custom_discount_amnt: discountAmount,
            custom_trade_offer_total: tradeOfferTotal,
            custom_gst_amount: 0,
            custom_advance_tax_amount: 0,
            custom_fed_amount: 0
        };

        let fedAmount = 0;

        if (row.custom_fed_formula) {
            fedAmount = await calculateFormula(
                row.custom_fed_formula,
                namespace
            );
        } else if (fedPer) {
            fedAmount =
                vendorRate *
                paidQty *
                fedPer /
                100;
        }

        namespace.custom_fed_amount = fedAmount;

        const gstAmount = await calculateFormula(
            row.custom_gst_formula,
            namespace
        );

        namespace.custom_gst_amount = gstAmount;

        const advanceTaxAmount = await calculateFormula(
            row.custom_advance_tax_formula,
            namespace
        );

        const rowNetAmount =
            grossTotal -
            discountAmount -
            tradeOfferTotal +
            fedAmount;

        const netUnitCost = qty
            ? rowNetAmount / qty
            : 0;

        const lineTotal =
            rowNetAmount +
            gstAmount +
            advanceTaxAmount;

        const values = {
            custom_vendor_rate: flt4(vendorRate),
            custom_gross_total: flt4(grossTotal),
            custom_discount_amnt: flt4(discountAmount),
            custom_trade_offer_total:
                flt4(tradeOfferTotal),
            custom_fed_amount: flt4(fedAmount),
            custom_gst_amount: flt4(gstAmount),
            custom_advance_tax_amount:
                flt4(advanceTaxAmount),
            custom_price_without_taxes:
                flt4(netUnitCost),
            custom_price_after_taxes:
                flt4(qty ? lineTotal / qty : 0),
            custom_line_total: flt4(lineTotal),

            // Server will enforce this again.
            price_list_rate: flt4(vendorRate),
            rate: flt4(netUnitCost),

            // Stop ERPNext standard discount from applying again.
            discount_percentage: 0,
            discount_amount: 0
        };

        for (const [fieldname, value] of Object.entries(values)) {
            if (flt(row[fieldname]) !== flt(value)) {
                await frappe.model.set_value(
                    cdt,
                    cdn,
                    fieldname,
                    value
                );
            }
        }
    }

    async function calculateDocument(frm) {
        if (calculationRunning || frm.doc.docstatus !== 0) {
            return;
        }

        calculationRunning = true;

        try {
            await frm.set_value("ignore_pricing_rule", 1);

            for (const row of frm.doc.items || []) {
                await calculateRow(
                    frm,
                    row.doctype,
                    row.name
                );
            }

            const totals = (frm.doc.items || []).reduce(
                (acc, row) => {
                    acc.gross += flt(
                        row.custom_gross_total
                    );

                    acc.discount += flt(
                        row.custom_discount_amnt
                    );

                    acc.trade += flt(
                        row.custom_trade_offer_total
                    );

                    acc.fed += flt(
                        row.custom_fed_amount
                    );

                    acc.gst += flt(
                        row.custom_gst_amount
                    );

                    acc.advance += flt(
                        row.custom_advance_tax_amount
                    );

                    acc.grand += flt(
                        row.custom_line_total
                    );

                    return acc;
                },
                {
                    gross: 0,
                    discount: 0,
                    trade: 0,
                    fed: 0,
                    gst: 0,
                    advance: 0,
                    grand: 0
                }
            );

            await frm.set_value({
                custom_total_gross: flt4(totals.gross),
                custom_total_discount:
                    flt4(totals.discount),
                custom_total_trade_offer:
                    flt4(totals.trade),
                custom_total_fed: flt4(totals.fed),
                custom_total_gst: flt4(totals.gst),
                custom_total_advance_tax:
                    flt4(totals.advance),
                custom_grand_line_total:
                    flt4(totals.grand)
            });

            frm.refresh_fields();
        } catch (error) {
            console.error(
                "Custom purchase calculation failed:",
                error
            );

            frappe.msgprint({
                title: __("Calculation Error"),
                indicator: "red",
                message: frappe.utils.escape_html(
                    error.message || String(error)
                )
            });
        } finally {
            calculationRunning = false;
        }
    }

    function scheduleCalculation(frm) {
        clearTimeout(calculationTimer);

        calculationTimer = setTimeout(() => {
            calculateDocument(frm);
        }, 250);
    }

    function showCalculationPreview(frm) {
        const rows = (frm.doc.items || [])
            .map(row => `
                <tr>
                    <td>${frappe.utils.escape_html(
                        row.item_code || ""
                    )}</td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_vendor_rate,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">${flt(row.qty)}</td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_gross_total,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_discount_amnt,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_trade_offer_total,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_fed_amount,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_gst_amount,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_advance_tax_amount,
                            frm.doc.currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_line_total,
                            frm.doc.currency
                        )}
                    </td>
                </tr>
            `)
            .join("");

        frappe.msgprint({
            title: __("Live Purchase Calculation"),
            indicator: "blue",
            wide: true,
            message: `
                <div style="overflow-x:auto">
                    <table class="table table-bordered">
                        <thead>
                            <tr>
                                <th>Item</th>
                                <th>Vendor Rate</th>
                                <th>Qty</th>
                                <th>Gross</th>
                                <th>Discount</th>
                                <th>Trade Offer</th>
                                <th>FED</th>
                                <th>GST</th>
                                <th>Advance Tax</th>
                                <th>Line Total</th>
                            </tr>
                        </thead>
                        <tbody>${rows}</tbody>
                    </table>

                    <hr>

                    <b>Gross:</b>
                    ${format_currency(
                        frm.doc.custom_total_gross,
                        frm.doc.currency
                    )}<br>

                    <b>Discount:</b>
                    ${format_currency(
                        frm.doc.custom_total_discount,
                        frm.doc.currency
                    )}<br>

                    <b>Trade Offer:</b>
                    ${format_currency(
                        frm.doc.custom_total_trade_offer,
                        frm.doc.currency
                    )}<br>

                    <b>FED:</b>
                    ${format_currency(
                        frm.doc.custom_total_fed,
                        frm.doc.currency
                    )}<br>

                    <b>GST:</b>
                    ${format_currency(
                        frm.doc.custom_total_gst,
                        frm.doc.currency
                    )}<br>

                    <b>Advance Tax:</b>
                    ${format_currency(
                        frm.doc.custom_total_advance_tax,
                        frm.doc.currency
                    )}<br>

                    <b>Expected Invoice Total:</b>
                    ${format_currency(
                        frm.doc.custom_grand_line_total,
                        frm.doc.currency
                    )}
                </div>
            `
        });
    }

    frappe.ui.form.on("Purchase Invoice", {
        setup(frm) {
            frm.set_query(
                "custom_gst_formula",
                "items",
                () => ({
                    filters: {
                        formula_type: "gst"
                    }
                })
            );

            frm.set_query(
                "custom_advance_tax_formula",
                "items",
                () => ({
                    filters: {
                        formula_type: "advance_tax"
                    }
                })
            );

            frm.set_query(
                "custom_fed_formula",
                "items",
                () => ({
                    filters: {
                        formula_type: "fed"
                    }
                })
            );
        },

        onload(frm) {
            frm.set_value("ignore_pricing_rule", 1);
            setCommercialFieldsReadonly(frm);
        },

        refresh(frm) {
            setCommercialFieldsReadonly(frm);

            if (frm.doc.docstatus === 0) {
                frm.add_custom_button(
                    __("Recalculate Custom Costs"),
                    async () => {
                        await calculateDocument(frm);

                        frappe.show_alert({
                            message:
                                __("Custom values recalculated"),
                            indicator: "green"
                        });
                    },
                    __("Custom Calculation")
                );

                frm.add_custom_button(
                    __("Show Live Calculation"),
                    async () => {
                        await calculateDocument(frm);
                        showCalculationPreview(frm);
                    },
                    __("Custom Calculation")
                );
            }
        },

        validate(frm) {
            return calculateDocument(frm);
        },

        items_add(frm) {
            scheduleCalculation(frm);
        },

        items_remove(frm) {
            scheduleCalculation(frm);
        }
    });

    const rowTriggers = [
        "qty",
        "custom_vendor_rate",
        "custom_scheme_qty",
        "custom_discount_per",
        "custom_trade_offer",
        "custom_mrp",
        "custom_gst_per",
        "custom_gst_formula",
        "custom_advance_tax_per",
        "custom_advance_tax_formula",
        "custom_fed_per",
        "custom_fed_formula",
        "custom_is_3rd_schedule"
    ];

    const childEvents = {};

    rowTriggers.forEach(fieldname => {
        childEvents[fieldname] = function (
            frm,
            cdt,
            cdn
        ) {
            scheduleCalculation(frm);
        };
    });

    childEvents.purchase_receipt = function (frm) {
        setCommercialFieldsReadonly(frm);
        scheduleCalculation(frm);
    };

    childEvents.purchase_receipt_item = function (frm) {
        setCommercialFieldsReadonly(frm);
        scheduleCalculation(frm);
    };

    frappe.ui.form.on(
        "Purchase Invoice Item",
        childEvents
    );
})();

// ============================================================
// PURCHASE RECEIPT CLIENT SCRIPT
// ERPNext v16
//
// custom_vendor_rate = actual editable vendor price
// price_list_rate     = ERPNext fetched buying price, fallback only
// rate                = calculated net inventory unit cost
//
// GST and Advance Tax are previews only on Purchase Receipt.
// ============================================================

(() => {
    const formulaCache = {};

    let calculationRunning = false;
    let calculationQueued = false;
    let calculationTimer = null;

    function flt4(value) {
        return Math.round(flt(value || 0) * 10000) / 10000;
    }

    function different(value1, value2) {
        return Math.abs(
            flt(value1 || 0) - flt(value2 || 0)
        ) > 0.00005;
    }

    // ========================================================
    // ARITHMETIC PARSER
    // Supports + - * / and parentheses
    // ========================================================

    function evaluateArithmetic(expression) {
        const input = String(expression || "")
            .replace(/\s+/g, "");

        if (!input) {
            return 0;
        }

        let position = 0;

        function peek() {
            return input[position] || "";
        }

        function consume() {
            const value = input[position] || "";
            position = position + 1;
            return value;
        }

        function parseNumber() {
            let text = "";
            let decimalCount = 0;

            while (position < input.length) {
                const character = peek();

                if (
                    character >= "0" &&
                    character <= "9"
                ) {
                    text = text + consume();
                } else if (character === ".") {
                    decimalCount = decimalCount + 1;

                    if (decimalCount > 1) {
                        throw new Error(
                            "Invalid decimal number"
                        );
                    }

                    text = text + consume();
                } else {
                    break;
                }
            }

            if (!text || text === ".") {
                throw new Error(
                    `Invalid number at position ${position}`
                );
            }

            const value = Number(text);

            if (!Number.isFinite(value)) {
                throw new Error("Invalid numeric value");
            }

            return value;
        }

        function parseFactor() {
            if (peek() === "+") {
                consume();
                return parseFactor();
            }

            if (peek() === "-") {
                consume();
                return -parseFactor();
            }

            if (peek() === "(") {
                consume();

                const value = parseExpression();

                if (peek() !== ")") {
                    throw new Error(
                        "Missing closing parenthesis"
                    );
                }

                consume();

                return value;
            }

            return parseNumber();
        }

        function parseTerm() {
            let value = parseFactor();

            while (
                peek() === "*" ||
                peek() === "/"
            ) {
                const operator = consume();
                const rightValue = parseFactor();

                if (operator === "*") {
                    value = value * rightValue;
                } else {
                    if (rightValue === 0) {
                        throw new Error("Division by zero");
                    }

                    value = value / rightValue;
                }
            }

            return value;
        }

        function parseExpression() {
            let value = parseTerm();

            while (
                peek() === "+" ||
                peek() === "-"
            ) {
                const operator = consume();
                const rightValue = parseTerm();

                if (operator === "+") {
                    value = value + rightValue;
                } else {
                    value = value - rightValue;
                }
            }

            return value;
        }

        const result = parseExpression();

        if (position !== input.length) {
            throw new Error(
                `Unexpected character at position ${position}`
            );
        }

        return result;
    }

    function replaceVariables(expression, namespace) {
        let result = String(expression || "");

        Object.keys(namespace)
            .sort((first, second) => {
                return second.length - first.length;
            })
            .forEach(variableName => {
                const escapedName = variableName.replace(
                    /[.*+?^${}()|[\]\\]/g,
                    "\\$&"
                );

                result = result.replace(
                    new RegExp(
                        `\\b${escapedName}\\b`,
                        "g"
                    ),
                    String(
                        flt(namespace[variableName] || 0)
                    )
                );
            });

        if (/[A-Za-z_]/.test(result)) {
            throw new Error(
                `Unknown variable in formula: ${result}`
            );
        }

        return result;
    }

    async function getFormula(formulaName) {
        if (!formulaName) {
            return null;
        }

        if (formulaCache[formulaName]) {
            return formulaCache[formulaName];
        }

        const response = await frappe.db.get_value(
            "Tax Formula",
            formulaName,
            [
                "formula_string",
                "formula_type"
            ]
        );

        const formula = response.message || {};

        formulaCache[formulaName] = formula;

        return formula;
    }

    async function calculateFormula(
        formulaName,
        namespace
    ) {
        if (!formulaName) {
            return 0;
        }

        const formula = await getFormula(formulaName);
        const formulaString =
            formula && formula.formula_string
                ? formula.formula_string
                : "";

        if (!formulaString) {
            return 0;
        }

        const expression = replaceVariables(
            formulaString,
            namespace
        );

        return flt4(
            evaluateArithmetic(expression)
        );
    }

    // ========================================================
    // VENDOR RATE INITIALIZATION
    //
    // Important:
    // custom_vendor_rate is initialized only when blank.
    // Existing/user-edited values are never replaced using
    // price_list_rate.
    // ========================================================

    async function initializeVendorRate(cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        // Existing saved or manually entered vendor rate wins.
        if (flt(row.custom_vendor_rate) > 0) {
            return;
        }

        const fetchedRate = flt(
            row.price_list_rate ||
            row.rate ||
            0
        );

        if (fetchedRate > 0) {
            await frappe.model.set_value(
                cdt,
                cdn,
                "custom_vendor_rate",
                flt4(fetchedRate)
            );
        }
    }

    // ========================================================
    // THIRD SCHEDULE
    // ========================================================

    async function applyThirdScheduleFormula(cdt, cdn) {
        const row = locals[cdt][cdn];

        if (
            !row ||
            !cint(row.custom_is_3rd_schedule)
        ) {
            return;
        }

        const existingFormula = String(
            row.custom_gst_formula || ""
        ).toLowerCase();

        if (existingFormula.startsWith("3rd")) {
            return;
        }

        const records = await frappe.db.get_list(
            "Tax Formula",
            {
                filters: {
                    formula_type: "gst"
                },
                fields: [
                    "name",
                    "formula_name"
                ],
                limit: 100
            }
        );

        const matchingFormula = (
            records || []
        ).find(record => {
            const name = String(
                record.formula_name ||
                record.name ||
                ""
            ).toLowerCase();

            return name.includes("3rd schedule");
        });

        if (matchingFormula) {
            await frappe.model.set_value(
                cdt,
                cdn,
                "custom_gst_formula",
                matchingFormula.name
            );
        }
    }

    // ========================================================
    // UPDATE ROW WITHOUT UNNECESSARY EVENT LOOPS
    // ========================================================

    async function setRowValues(cdt, cdn, values) {
        const row = locals[cdt][cdn];

        for (
            const [fieldname, value]
            of Object.entries(values)
        ) {
            if (
                different(
                    row[fieldname],
                    value
                )
            ) {
                await frappe.model.set_value(
                    cdt,
                    cdn,
                    fieldname,
                    value
                );
            }
        }
    }

    // ========================================================
    // CALCULATE ONE ROW
    // ========================================================

    async function calculateRow(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row || !row.item_code) {
            return;
        }

        await initializeVendorRate(cdt, cdn);
        await applyThirdScheduleFormula(cdt, cdn);

        row = locals[cdt][cdn];

        // custom_vendor_rate always has priority.
        const vendorRate = flt(
            row.custom_vendor_rate || 0
        );

        const qty = flt(row.qty || 0);
        const schemeQty = flt(
            row.custom_scheme_qty || 0
        );
        const discountPer = flt(
            row.custom_discount_per || 0
        );
        const tradeOfferTotal = flt(
            row.custom_trade_offer_total || 0
        );
        const mrp = flt(
            row.custom_mrp || 0
        );
        const gstPer = flt(
            row.custom_gst_per || 0
        );
        const advanceTaxPer = flt(
            row.custom_advance_tax_per || 0
        );
        const fedPer = flt(
            row.custom_fed_per || 0
        );

        if (schemeQty < 0) {
            throw new Error(
                `Scheme quantity cannot be negative for ${row.item_code}`
            );
        }

        if (schemeQty > qty) {
            throw new Error(
                `Scheme quantity cannot exceed quantity for ${row.item_code}`
            );
        }

        if (
            discountPer < 0 ||
            discountPer > 100
        ) {
            throw new Error(
                `Discount must be between 0 and 100 for ${row.item_code}`
            );
        }

        const paidQty = qty - schemeQty;

        const grossTotal =
            vendorRate * qty;

        const discountAmount =
            vendorRate *
            discountPer /
            100 *
            paidQty;

        const tradeOffer =
            paidQty ?
            tradeOfferTotal / paidQty : 0;

        const namespace = {
            rate: vendorRate,
            qty: qty,
            custom_scheme_qty: schemeQty,
            custom_discount_per: discountPer,
            custom_trade_offer: tradeOffer,
            custom_mrp: mrp,
            custom_gst_per: gstPer,
            custom_advance_tax_per:
                advanceTaxPer,
            custom_fed_per: fedPer,
            custom_gross_total:
                grossTotal,
            custom_discount_amnt:
                discountAmount,
            custom_trade_offer_total:
                tradeOfferTotal,
            custom_gst_amount: 0,
            custom_advance_tax_amount: 0,
            custom_fed_amount: 0
        };

        let fedAmount = 0;

        if (row.custom_fed_formula) {
            fedAmount = await calculateFormula(
                row.custom_fed_formula,
                namespace
            );
        } else if (fedPer) {
            fedAmount =
                vendorRate *
                paidQty *
                fedPer /
                100;
        }

        fedAmount = flt4(fedAmount);

        namespace.custom_fed_amount =
            fedAmount;

        const gstAmount = flt4(
            await calculateFormula(
                row.custom_gst_formula,
                namespace
            )
        );

        namespace.custom_gst_amount =
            gstAmount;

        const advanceTaxAmount = flt4(
            await calculateFormula(
                row.custom_advance_tax_formula,
                namespace
            )
        );

        const inventoryAmount =
            grossTotal -
            discountAmount -
            tradeOfferTotal +
            fedAmount;

        const netUnitCost = qty
            ? inventoryAmount / qty
            : 0;

        const lineTotal =
            inventoryAmount +
            gstAmount +
            advanceTaxAmount;

        /*
         * Do not set price_list_rate here.
         *
         * ERPNext may have fetched an old Item Price, but it
         * must not replace custom_vendor_rate. Your On Submit
         * server script will update Item Price using the final
         * custom_vendor_rate.
         */

        await setRowValues(
            cdt,
            cdn,
            {
                custom_gross_total:
                    flt4(grossTotal),

                custom_discount_amnt:
                    flt4(discountAmount),

                custom_trade_offer_total:
                    flt4(tradeOfferTotal),

                custom_trade_offer:
                    flt4(tradeOffer),

                custom_fed_amount:
                    flt4(fedAmount),

                custom_gst_amount:
                    flt4(gstAmount),

                custom_advance_tax_amount:
                    flt4(advanceTaxAmount),

                custom_price_without_taxes:
                    flt4(netUnitCost),

                custom_price_after_taxes:
                    flt4(
                        qty
                            ? lineTotal / qty
                            : 0
                    ),

                custom_line_total:
                    flt4(lineTotal),

                // ERPNext stock/inventory rate
                rate:
                    flt4(netUnitCost),

                // Custom discount is already included
                discount_percentage: 0,
                discount_amount: 0,
                distributed_discount_amount: 0
            }
        );

        console.log(
            "PR custom calculation",
            {
                item_code: row.item_code,
                vendor_rate: vendorRate,
                price_list_rate:
                    row.price_list_rate,
                qty: qty,
                gross: grossTotal,
                discount: discountAmount,
                trade_offer:
                    tradeOfferTotal,
                fed: fedAmount,
                gst: gstAmount,
                advance_tax:
                    advanceTaxAmount,
                inventory_rate:
                    netUnitCost,
                line_total: lineTotal
            }
        );
    }

    // ========================================================
    // CUSTOM DOCUMENT TOTALS
    // ========================================================

    async function updateCustomTotals(frm) {
        const totals = (
            frm.doc.items || []
        ).reduce(
            (result, row) => {
                result.gross =
                    result.gross +
                    flt(
                        row.custom_gross_total
                    );

                result.discount =
                    result.discount +
                    flt(
                        row.custom_discount_amnt
                    );

                result.trade =
                    result.trade +
                    flt(
                        row.custom_trade_offer_total
                    );

                result.fed =
                    result.fed +
                    flt(
                        row.custom_fed_amount
                    );

                result.gst =
                    result.gst +
                    flt(
                        row.custom_gst_amount
                    );

                result.advance =
                    result.advance +
                    flt(
                        row.custom_advance_tax_amount
                    );

                result.grand =
                    result.grand +
                    flt(
                        row.custom_line_total
                    );

                return result;
            },
            {
                gross: 0,
                discount: 0,
                trade: 0,
                fed: 0,
                gst: 0,
                advance: 0,
                grand: 0
            }
        );

        const values = {
            custom_total_gross:
                flt4(totals.gross),

            custom_total_discount:
                flt4(totals.discount),

            custom_total_trade_offer:
                flt4(totals.trade),

            custom_total_fed:
                flt4(totals.fed),

            custom_total_gst:
                flt4(totals.gst),

            custom_total_advance_tax:
                flt4(totals.advance),

            custom_grand_line_total:
                flt4(totals.grand)
        };

        for (
            const [fieldname, value]
            of Object.entries(values)
        ) {
            if (
                different(
                    frm.doc[fieldname],
                    value
                )
            ) {
                await frm.set_value(
                    fieldname,
                    value
                );
            }
        }
    }

    // ========================================================
    // CALCULATE DOCUMENT
    // ========================================================

    async function calculateDocument(frm) {
        if (frm.doc.docstatus !== 0) {
            return;
        }

        if (calculationRunning) {
            calculationQueued = true;
            return;
        }

        calculationRunning = true;
        calculationQueued = false;

        try {
            if (!frm.doc.ignore_pricing_rule) {
                await frm.set_value(
                    "ignore_pricing_rule",
                    1
                );
            }

            for (
                const row of frm.doc.items || []
            ) {
                await calculateRow(
                    frm,
                    row.doctype,
                    row.name
                );
            }

            await updateCustomTotals(frm);

            frm.refresh_field("items");
            frm.refresh_fields();

        } catch (error) {
            console.error(
                "Purchase Receipt calculation failed",
                error
            );

            frappe.msgprint({
                title: __(
                    "Purchase Receipt Calculation Error"
                ),
                indicator: "red",
                message:
                    frappe.utils.escape_html(
                        error.message ||
                        String(error)
                    )
            });
        } finally {
            calculationRunning = false;

            if (calculationQueued) {
                calculationQueued = false;
                scheduleCalculation(frm, 300);
            }
        }
    }

    function scheduleCalculation(
        frm,
        delay = 250
    ) {
        clearTimeout(calculationTimer);

        calculationTimer = setTimeout(
            function () {
                calculateDocument(frm);
            },
            delay
        );
    }

