// Purchase Receipt – Excel-like Items grid
// Frozen left columns + frozen right action column + sticky header
// + full-screen toggle.

/*
 * Small debounce helper. Without this, every cell edit fires a full
 * DOM re-scan + header re-measure on each change event, which causes
 * lag and flicker on larger grids. Debouncing coalesces rapid changes
 * into a single update.
 */
function excel_grid_debounce(fn, wait) {
    let timer = null;

    return function (...args) {
        if (timer) {
            clearTimeout(timer);
        }

        timer = setTimeout(() => {
            timer = null;
            fn.apply(this, args);
        }, wait);
    };
}


frappe.ui.form.on("Purchase Receipt", {
    onload_post_render(frm) {
        // Grid DOM exists after first render; give it a beat to settle.
        setTimeout(() => setup_items_excel_grid(frm), 200);
    },

    refresh(frm) {
        // Grid is rebuilt on refresh, so re-apply our enhancements.
        setTimeout(() => setup_items_excel_grid(frm), 200);
    },
});


function setup_items_excel_grid(frm) {
    const grid = frm.fields_dict.items?.grid;

    if (!grid || !grid.wrapper) {
        return;
    }

    inject_items_excel_css();
    inject_items_grid_overlap_fix_css();

    const $wrapper = $(grid.wrapper);

    $wrapper.addClass("excel-items-grid");

    // Add toolbar once
    if (!$wrapper.children(".excel-grid-toolbar").length) {
        const $toolbar = $(`
            <div class="excel-grid-toolbar">
                <div class="excel-grid-toolbar-left">
                    <strong>Items Spreadsheet</strong>
                    <span class="excel-grid-row-count"></span>
                    <span class="excel-grid-help">Esc to close full screen</span>
                </div>

                <button
                    type="button"
                    class="btn btn-primary btn-sm excel-grid-toggle"
                    aria-pressed="false"
                >
                    ⛶ Full Screen
                </button>
            </div>
        `);

        $wrapper.prepend($toolbar);
    }

    update_items_grid_count(frm, $wrapper);
    mark_items_grid_sticky_columns($wrapper);
    queue_items_grid_header_sync($wrapper);

    const $toggle_button = $wrapper.find(
        "> .excel-grid-toolbar .excel-grid-toggle"
    );

    $toggle_button
        .off("click.excelItemsGrid")
        .on("click.excelItemsGrid", function (event) {
            event.preventDefault();
            event.stopPropagation();

            const enable = !$wrapper.hasClass(
                "excel-items-grid-fullscreen"
            );

            set_items_grid_fullscreen($wrapper, enable);
        });

    /*
     * Grid refreshes recreate row elements.
     * Reapply sticky classes + count after changes.
     *
     * Sticky-class marking is cheap, so it runs immediately inside an
     * animation frame. The expensive header re-measure is debounced so
     * rapid edits (typing in a cell, paste, bulk changes) don't trigger
     * dozens of reflows.
     */
    const debounced_header_sync = excel_grid_debounce(() => {
        queue_items_grid_header_sync($wrapper);
    }, 180);

    $wrapper
        .off("change.excelItemsGrid")
        .on("change.excelItemsGrid", function () {
            window.requestAnimationFrame(() => {
                mark_items_grid_sticky_columns($wrapper);
                update_items_grid_count(frm, $wrapper);
            });
            debounced_header_sync();
        });

    // Allow the scrolling area to receive keyboard focus
    $wrapper.find(".form-grid-container").attr("tabindex", "0");

    // Esc closes full-screen mode, but not while a dialog is open
    $(document)
        .off("keydown.excelItemsGrid")
        .on("keydown.excelItemsGrid", function (event) {
            if (
                event.key === "Escape" &&
                $(".excel-items-grid-fullscreen").length &&
                !$(".modal.show").length
            ) {
                event.preventDefault();

                const $open_grid = $(
                    ".excel-items-grid-fullscreen"
                ).first();

                set_items_grid_fullscreen($open_grid, false);
            }
        });
}


function update_items_grid_count(frm, $wrapper) {
    const row_count = Array.isArray(frm.doc.items)
        ? frm.doc.items.length
        : 0;

    $wrapper
        .find("> .excel-grid-toolbar .excel-grid-row-count")
        .text(`${row_count} ${row_count === 1 ? "row" : "rows"}`);
}


function mark_items_grid_sticky_columns($wrapper) {
    $wrapper
        .find(
            ".excel-sticky-check, " +
            ".excel-sticky-index, " +
            ".excel-sticky-item, " +
            ".excel-sticky-right"
        )
        .removeClass(
            "excel-sticky-check " +
            "excel-sticky-index " +
            "excel-sticky-item " +
            "excel-sticky-right"
        );

    // Left checkbox column
    $wrapper
        .find(".data-row > .row-check")
        .addClass("excel-sticky-check");

    // Left row number column
    $wrapper
        .find(".data-row > .row-index")
        .addClass("excel-sticky-index");

    // Freeze Item Code like Excel's first important column
    $wrapper
        .find('.data-row > [data-fieldname="item_code"]')
        .addClass("excel-sticky-item");

    // Keep edit button visible and clickable on every item row
    $wrapper.find(".btn-open-row").each(function () {
        $(this)
            .closest(".col")
            .addClass("excel-sticky-right");
    });

    // Keep gear/settings column and search-row ending column visible
    $wrapper
        .find(".grid-heading-row .data-row")
        .each(function () {
            $(this)
                .children(".col")
                .last()
                .addClass("excel-sticky-right");
        });
}


function set_items_grid_fullscreen($wrapper, enable) {
    // Close any other full-screen grid first
    $(".excel-items-grid-fullscreen")
        .not($wrapper)
        .removeClass("excel-items-grid-fullscreen");

    $wrapper.toggleClass("excel-items-grid-fullscreen", enable);

    $("body").toggleClass("excel-items-grid-body-lock", enable);

    const $button = $wrapper.find(
        "> .excel-grid-toolbar .excel-grid-toggle"
    );

    $button
        .attr("aria-pressed", enable ? "true" : "false")
        .text(enable ? "× Close Full Screen" : "⛶ Full Screen");

    setTimeout(() => {
        mark_items_grid_sticky_columns($wrapper);
        queue_items_grid_header_sync($wrapper);

        if (enable) {
            $wrapper.find(".form-grid-container").trigger("focus");
        }
    }, 100);
}


function queue_items_grid_header_sync($wrapper) {
    const old_timer = $wrapper.data("excel-grid-header-sync-timer");

    if (old_timer) {
        clearTimeout(old_timer);
    }

    const timer = setTimeout(() => {
        const heading =
            $wrapper
                .find(".form-grid-container > .grid-heading-row")
                .get(0) ||
            $wrapper.find(".grid-heading-row").get(0);

        if (!heading) {
            return;
        }

        /*
         * Remove the fixed height first so both:
         * 1. column heading row
         * 2. filter/search row
         * can be measured.
         */
        heading.style.setProperty("height", "auto", "important");
        heading.style.setProperty("min-height", "0", "important");
        heading.style.setProperty("overflow", "visible", "important");

        window.requestAnimationFrame(() => {
            const visible_rows = Array.from(heading.children).filter(
                (element) => {
                    return (
                        element.classList.contains("grid-row") &&
                        element.offsetParent !== null
                    );
                }
            );

            const measured_height = visible_rows.reduce(
                (total, element) => {
                    return (
                        total +
                        element.getBoundingClientRect().height
                    );
                },
                0
            );

            // Single label row, but text may wrap to ~2 lines.
            const fallback_height = 46;

            const final_height = Math.max(
                Math.ceil(measured_height),
                fallback_height
            );

            heading.style.setProperty(
                "height",
                `${final_height}px`,
                "important"
            );

            heading.style.setProperty(
                "min-height",
                `${final_height}px`,
                "important"
            );

            $wrapper
                .get(0)
                ?.style.setProperty(
                    "--excel-heading-height",
                    `${final_height}px`
                );
        });
    }, 50);

    $wrapper.data("excel-grid-header-sync-timer", timer);
}


