/**
 * Purchase Invoice – Excel-like Items Grid
 * 
 * Features:
 * - Frozen left columns (checkbox, index) + frozen item code + frozen right action column
 * - Sticky header with automatic height detection
 * - Full-screen toggle with keyboard support
 * - Optimized performance with debouncing and RAF scheduling
 * - Responsive design with mobile fallbacks
 * - Accessibility-first implementation (ARIA labels, focus management, keyboard nav)
 * 
 * @module purchase-Invoice-grid
 */

/**
 * Performance-optimized debounce helper
 * Coalesces rapid changes into single update to prevent DOM thrashing
 * 
 * @param {Function} fn - Function to debounce
 * @param {number} wait - Delay in milliseconds
 * @returns {Function} Debounced function
 */
function excel_grid_debounce(fn, wait) {
    let timer = null;

    return function (...args) {
        if (timer) clearTimeout(timer);
        timer = setTimeout(() => {
            timer = null;
            fn.apply(this, args);
        }, wait);
    };
}

/**
 * Request animation frame throttle helper
 * Ensures visual updates happen at screen refresh rate
 * 
 * @param {Function} fn - Function to throttle
 * @returns {Function} Throttled function
 */
function excel_grid_raf_throttle(fn) {
    let rafId = null;
    let pending = false;

    return function (...args) {
        if (pending) return;
        pending = true;

        rafId = requestAnimationFrame(() => {
            fn.apply(this, args);
            pending = false;
        });
    };
}

