        }

        @media (max-width: 900px) {
            .excel-grid-help {
                display: none;
            }

            .excel-items-grid {
                --excel-grid-min-width: 1400px;
                --excel-item-width: 260px;
            }
        }
    `;

    $("<style>", {
        id: "items-excel-grid-css",
        text: css,
    }).appendTo("head");
}

